* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  width: 100%;
  min-width: 0;
  font-family: "Segoe UI", Inter, -apple-system, BlinkMacSystemFont, sans-serif;
  background: transparent;
}

body {
  overflow-x: hidden;
}

.dashboard-container {
  display: grid;
  width: 100%;
  padding: 4px;
  align-items: stretch;
}

/* Main tile */
.dashboard-tile {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 14px 15px 14px 19px;
  background: #ffffff;
  border: 1px solid #dce7f5;
  border-radius: 9px;
  box-shadow: 0 1px 3px rgba(30, 64, 110, 0.025);
  cursor: pointer;
  user-select: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease;
}

.dashboard-tile:hover {
  border-color: #b8cde8;
  box-shadow: 0 4px 12px rgba(39, 76, 125, 0.08);
}

.dashboard-tile:active {
  transform: translateY(1px);
}

.dashboard-tile.has-subtiles {
  grid-row: span 2;
  justify-content: flex-start;
  padding-top: 20px;
}

/* Icon + title + count + arrow */
.tile-header-container {
  display: grid;
  grid-template-columns: 49px minmax(0, 1fr) 13px;
  align-items: center;
  column-gap: 14px;
  width: 100%;
  min-width: 0;
}

/* Automatic pastel icon circle */
.tile-icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 49px;
  height: 49px;
  flex-shrink: 0;
  color: var(--icon-color, #1677f5);
  background: var(--icon-bg, #eaf3ff);
  border: 1px solid var(--icon-border, #d5e6ff);
  border-radius: 50%;
}

.tile-icon {
  display: block;
  width: 24px;
  height: 24px;
}

/* Text */
.tile-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  gap: 7px;
}

.tile-name {
  margin: 0;
  color: #193253;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.15px;
  text-transform: none;
  overflow-wrap: anywhere;
}

.tile-count {
  margin: 0;
  color: #10284b;
  font-size: 27px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.7px;
  font-variant-numeric: tabular-nums;
}

/* Right-facing chevron */
.tile-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 13px;
  height: 22px;
  color: #8299ba;
  transition: color 0.18s ease, transform 0.18s ease;
}

.tile-arrow svg {
  display: block;
  width: 15px;
  height: 20px;
}

.dashboard-tile:hover .tile-arrow {
  color: #2563eb;
  transform: translateX(2px);
}

/* Selected state */
.dashboard-tile.is-selected {
  border-color: #4789ed;
  background: #f4f8ff;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.14);
}

.dashboard-tile.is-selected .tile-arrow {
  color: #2563eb;
}

/* Sub-tiles */
.sub-tiles-container {
  display: flex;
  flex-direction: column;
  gap: 9px;
  width: 100%;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #e7edf5;
}

.sub-tile {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-width: 0;
  padding: 12px 13px;
  background: #f8faff;
  border: 1px solid #e1e9f4;
  border-radius: 7px;
  cursor: pointer;
  transition: border-color 0.18s ease, background-color 0.18s ease;
}

.sub-tile:hover {
  background: #f0f6ff;
  border-color: #c7d9f0;
}

.sub-tile.is-selected {
  background: #edf5ff;
  border-color: #4789ed;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.12);
}

.sub-tile-name {
  min-width: 0;
  color: #536783;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.sub-tile-count {
  flex-shrink: 0;
  color: #142b4d;
  font-size: 17px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

/* Loading */
.dashboard-loading {
  padding: 20px;
  color: #64748b;
  text-align: center;
  font-size: 13px;
}

/* Responsive sizing */
@media (max-width: 1100px) {
  .dashboard-tile {
    padding: 12px;
  }
  .tile-header-container {
    grid-template-columns: 40px minmax(0, 1fr) 12px;
    column-gap: 10px;
  }
  .tile-icon-wrapper {
    width: 40px;
    height: 40px;
  }
  .tile-icon {
    width: 21px;
    height: 21px;
  }
  .tile-name {
    font-size: 12px;
  }
  .tile-count {
    font-size: 24px;
  }
}
@media (max-width: 700px) {
  .dashboard-container {
    padding: 4px;
    gap: 10px;
  }
  .dashboard-tile {
    padding: 12px 10px;
  }
  .tile-header-container {
    grid-template-columns: 34px minmax(0, 1fr) 10px;
    column-gap: 8px;
  }
  .tile-icon-wrapper {
    width: 34px;
    height: 34px;
  }
  .tile-icon {
    width: 19px;
    height: 19px;
  }
  .tile-name {
    font-size: 11px;
  }
  .tile-count {
    font-size: 21px;
  }
  .tile-info {
    gap: 6px;
  }
}

