/* Automatically choose an icon based on the tile name. */
function getTileIcon(name = "") {
  const n = name.toLowerCase();

  if (n.includes("oa/arc") || n.includes("qa/arc")) return "document";
  if (n.includes("consistency") || n.includes("vendor")) return "users";
  if (n.includes("rfq")) return "send";
  if (n.includes("bid submission") || n.includes("commercial")) {
    return n.includes("commercial") ? "chart" : "gavel";
  }
  if (n.includes("technical")) return "shield";
  if (n.includes("e-nfa") || n.includes("approval")) return "approval";
  if (n.includes("created")) return "box";
  if (n.includes("released") || n.includes("purchase order")) return "truck";
  if (n.includes("manual") || n.includes("route")) return "route";

  return "document";
}

/* Different pastel colors, following the reference image. */
const TILE_COLORS = [
  { bg: "#eaf3ff", border: "#d5e6ff", color: "#1677f5" },
  { bg: "#e5f9ef", border: "#c9f0dc", color: "#14965d" },
  { bg: "#f0ecff", border: "#e0d7ff", color: "#6543e8" },
  { bg: "#fff1df", border: "#ffe2bd", color: "#e98213" },
  { bg: "#e0f8f8", border: "#c0eeee", color: "#078b8b" },
  { bg: "#eaf3ff", border: "#d5e6ff", color: "#1677f5" },
  { bg: "#f0ecff", border: "#e0d7ff", color: "#6543e8" },
  { bg: "#e0f8f8", border: "#c0eeee", color: "#078b8b" },
  { bg: "#f0ecff", border: "#e0d7ff", color: "#6543e8" },
  { bg: "#ffeaf0", border: "#ffd4e0", color: "#ed4776" }
];

function TileIcon({ name, index }) {
  const iconName = getTileIcon(name);
  const palette = TILE_COLORS[index % TILE_COLORS.length];

  return (
    <div
      className="tile-icon-wrapper"
      style={{
        "--icon-bg": palette.bg,
        "--icon-border": palette.border,
        "--icon-color": palette.color
      }}
    >
      <svg
        className="tile-icon"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.9"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
      >
        {ICONS[iconName]}
      </svg>
    </div>
  );
}

function App() {
  const [model, setModel] = React.useState(appsmith.model || {});

  React.useEffect(() => {
    const handleModelChange = (newModel) => {
      if (newModel) setModel(newModel);
    };

    appsmith.onModelChange(handleModelChange);
  }, []);

  const handleTileClick = (filterValue, e) => {
    if (e) e.stopPropagation();

    if (filterValue) {
      if (appsmith.updateModel) {
        const newFilter =
          model.selectedFilter === filterValue ? "" : filterValue;

        appsmith.updateModel({ clickedFilter: newFilter });
      }

      if (appsmith.triggerEvent) {
        appsmith.triggerEvent("onTileClick");
      }
    }
  };

  if (!model.tiles || !Array.isArray(model.tiles)) {
    return (
      <div className="dashboard-loading">
        Loading Dashboard Metrics...
      </div>
    );
  }

  return (
    <div
      className="dashboard-container"
      style={{
        gridTemplateColumns: `repeat(${model.layout?.columns || 4}, minmax(0, 1fr))`,
        gridAutoRows: "113px",
        gap: model.layout?.gap || "16px"
      }}
    >
      {[...model.tiles]
        .sort((a, b) => (a.SortOrder || 0) - (b.SortOrder || 0))
        .map((tile, index) => (
          <div
            key={tile.FilterValue || tile.TileName}
            className={`dashboard-tile ${
              tile.SubTiles?.length > 0 ? "has-subtiles" : ""
            } ${
              model.selectedFilter === tile.FilterValue
                ? "is-selected"
                : ""
            }`}
            onClick={(e) => handleTileClick(tile.FilterValue, e)}
          >
            <div className="tile-header-container">
              <TileIcon name={tile.TileName} index={index} />

              <div className="tile-info">
                <div className="tile-name">{tile.TileName}</div>
                <div className="tile-count">{tile.TileCount}</div>
              </div>

              <div className="tile-arrow" aria-hidden="true">
                <svg viewBox="0 0 24 24" fill="none">
                  <path
                    d="m9 5 7 7-7 7"
                    stroke="currentColor"
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
            </div>

            {tile.SubTiles && tile.SubTiles.length > 0 && (
              <div className="sub-tiles-container">
                {tile.SubTiles.map((sub) => (
                  <div
                    key={sub.FilterValue || sub.TileName}
                    className={`sub-tile ${
                      model.selectedFilter === sub.FilterValue
                        ? "is-selected"
                        : ""
                    }`}
                    onClick={(e) =>
                      handleTileClick(sub.FilterValue, e)
                    }
                  >
                    <div className="sub-tile-name">
                      {sub.TileName}
                    </div>
                    <div className="sub-tile-count">
                      {sub.TileCount}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
    </div>
  );
}

appsmith.onReady(() => {
  ReactDOM.render(<App />, document.getElementById("root"));
});
